"""Settings from the environment (``.env`` via python-dotenv). Secrets never leave here."""

from __future__ import annotations

import os
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Literal

from dotenv import load_dotenv

ROOT = Path(__file__).resolve().parent.parent


LineKind = Literal["release", "eval", "distro"]


@dataclass(frozen=True)
class LineSpec:
    """A target line: a tip commit plus where its upstream fixes come from.

    ``kind`` is ``release`` (the fork's maintained line), ``eval`` (backtest trees)
    or ``distro`` (a distribution's patched tree). Only release lines may publish;
    constructing an eval or distro line with ``publish=True`` is an error.
    """

    name: str
    tip: str  # commit-ish of the line's tip
    upstream: str  # preferred security.txt branch series whose fix we port
    base_branch: str | None = None  # fork branch PRs target (publishing lines only)
    kind: LineKind = "release"
    publish: bool = False
    upstream_fallbacks: tuple[str, ...] = ()
    # Extra regression labels per touched module, on top of the upstream test labels.
    test_labels: dict[str, tuple[str, ...]] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if self.kind not in ("release", "eval", "distro"):
            raise ValueError(f"unknown line kind {self.kind!r}")
        if self.publish and self.kind != "release":
            raise ValueError(f"{self.kind} line {self.name!r} can never publish")
        if self.publish and not self.base_branch:
            raise ValueError(f"publishing line {self.name!r} needs a base_branch")

    @property
    def upstreams(self) -> tuple[str, ...]:
        return tuple(dict.fromkeys((self.upstream, *self.upstream_fallbacks)))

    def to_json(self) -> dict[str, Any]:
        d = asdict(self)
        d["upstream_fallbacks"] = list(self.upstream_fallbacks)
        d["test_labels"] = {k: list(v) for k, v in self.test_labels.items()}
        return d

    @classmethod
    def from_json(cls, d: dict[str, Any]) -> LineSpec:
        return cls(
            **{
                **d,
                "upstream_fallbacks": tuple(d.get("upstream_fallbacks", ())),
                "test_labels": {k: tuple(v) for k, v in d.get("test_labels", {}).items()},
            }
        )


DJANGO_42_LABELS: dict[str, tuple[str, ...]] = {
    "django/forms/models.py": ("model_forms", "model_formsets", "inline_formsets"),
    "django/utils/translation/": ("i18n",),
}

LINES: dict[str, LineSpec] = {
    "4.2": LineSpec(
        name="4.2",
        tip="3396992e837d5146270ea8112bb622c83fa4a919",  # tag 4.2.30
        upstream="5.2",
        upstream_fallbacks=("5.1", "5.0"),
        base_branch="stable/4.2.x-heirloom",
        kind="release",
        publish=True,
        test_labels=DJANGO_42_LABELS,
    )
}


def runtime_line(name: str, tip: str, kind: LineKind, *, like: str = "4.2") -> LineSpec:
    """A non-publishing line built at runtime (backtest trees, distro trees)."""
    if kind == "release":
        raise ValueError("runtime lines are eval or distro lines; release lines live in LINES")
    base = LINES[like]
    return LineSpec(
        name=name,
        tip=tip,
        upstream=base.upstream,
        upstream_fallbacks=base.upstream_fallbacks,
        kind=kind,
        publish=False,
        test_labels=base.test_labels,
    )


@dataclass(frozen=True)
class Settings:
    root: Path
    work: Path
    django_repo: Path
    test_python: Path
    fork: str  # owner/repo
    fork_remote: str
    heirloom_repo: str  # owner/repo of this project (artifacts branch, questions)
    artifacts_branch: str
    litellm_base: str
    litellm_key: str
    openrouter_key: str
    max_usd_per_cve: float
    max_overflow_usd: float  # total spend allowed on overflow keys once LiteLLM is exhausted
    neatlogs_api_key: str
    neatlogs_service_token: str
    neatlogs_project_id: str
    neatlogs_trace_url: str
    probe_model: str
    reading_model: str
    adapt_model: str
    test_timeout: float

    @property
    def ledger_path(self) -> Path:
        return self.work / "ledger.sqlite"

    def cve_dir(self, cve: str, line: str) -> Path:
        return self.work / "cve" / f"{cve}-{line}"

    def secrets(self) -> list[str]:
        values = [
            self.litellm_key,
            self.openrouter_key,
            self.neatlogs_api_key,
            self.neatlogs_service_token,
        ]
        return [v for v in values if len(v) >= 8]


def load(env_file: Path | None = None) -> Settings:
    load_dotenv(env_file or ROOT / ".env", override=False)
    e = os.environ.get
    work = Path(e("HEIRLOOM_WORK", str(ROOT / "work")))
    return Settings(
        root=ROOT,
        work=work,
        django_repo=Path(e("HEIRLOOM_DJANGO_REPO", str(Path.home() / "work" / "django"))),
        test_python=Path(e("HEIRLOOM_TEST_PYTHON", str(work / "venv-django" / "bin" / "python"))),
        fork=e("HEIRLOOM_FORK", "iamdflame/django") or "iamdflame/django",
        fork_remote=e("HEIRLOOM_FORK_REMOTE", "fork") or "fork",
        heirloom_repo=e("HEIRLOOM_REPO", "iamdflame/heirloom") or "iamdflame/heirloom",
        artifacts_branch=e("HEIRLOOM_ARTIFACTS_BRANCH", "artifacts") or "artifacts",
        litellm_base=e("LITELLM_BASE_URL", "https://litellm.vision.aivar.app/v1") or "",
        litellm_key=e("LITELLM_API_KEY", "") or "",
        openrouter_key=e("OPENROUTER_API_KEY", "") or "",
        max_usd_per_cve=float(e("HEIRLOOM_MAX_USD_PER_CVE", "1.50") or "1.50"),
        max_overflow_usd=float(e("HEIRLOOM_MAX_OVERFLOW_USD", "25") or "25"),
        neatlogs_api_key=e("NEATLOGS_API_KEY", "") or "",
        neatlogs_service_token=e("NEATLOGS_SERVICE_TOKEN", "") or "",
        neatlogs_project_id=e("NEATLOGS_PROJECT_ID", "") or "",
        # The app does not document deep links; override once confirmed in the UI.
        neatlogs_trace_url=e(
            "NEATLOGS_TRACE_URL", "https://app.neatlogs.com/traces/{trace_id}?span={span_id}"
        )
        or "",
        probe_model=e("HEIRLOOM_PROBE_MODEL", "claude-sonnet-4.6") or "claude-sonnet-4.6",
        reading_model=e("HEIRLOOM_READING_MODEL", "claude-haiku") or "claude-haiku",
        adapt_model=e("HEIRLOOM_ADAPT_MODEL", "claude-sonnet-4.6") or "claude-sonnet-4.6",
        test_timeout=float(e("HEIRLOOM_TEST_TIMEOUT", "900") or "900"),
    )
"""LiteLLM calls through the gateway, with a hard per-CVE budget.

``litellm`` is imported lazily so ``neatlogs.init()`` can run first and
instrument it. The gateway reports ``totalCostUsd: 0``, so cost is computed
here from token usage at list prices (estimates, recorded on every span).
"""

from __future__ import annotations

from collections.abc import Callable, Sequence
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from heirloom.config import Settings

# USD per million tokens (input, output): Anthropic list prices for the
# Sonnet 4.x and Haiku 4.5 tiers; Amazon Nova Lite list price.
PRICES: dict[str, tuple[float, float]] = {
    "claude-sonnet-4.6": (3.0, 15.0),
    "claude-haiku": (1.0, 5.0),
    "nova-lite": (0.06, 0.24),
}
OPENROUTER_MODELS = {"claude-sonnet-4.6": "anthropic/claude-sonnet-4.6"}


class BudgetExceeded(RuntimeError):
    pass


@dataclass
class Budget:
    limit_usd: float
    spent: Callable[[], float]

    def remaining(self) -> float:
        return self.limit_usd - self.spent()

    def check(self, needed: float = 0.0) -> None:
        if self.remaining() <= needed:
            raise BudgetExceeded(
                f"budget exhausted: spent ${self.spent():.4f} of ${self.limit_usd:.2f}"
            )


@dataclass(frozen=True)
class Completion:
    text: str
    model: str
    input_tokens: int
    output_tokens: int
    cost_usd: float
    provider: str


def cost_of(model: str, input_tokens: int, output_tokens: int) -> float:
    pin, pout = PRICES.get(model, PRICES["claude-sonnet-4.6"])
    return (input_tokens * pin + output_tokens * pout) / 1_000_000


def key_info(settings: Settings) -> dict[str, Any]:
    """LiteLLM ``/key/info`` budget fields for our key (spend, max_budget, reset)."""
    import httpx

    base = settings.litellm_base.removesuffix("/v1")
    r = httpx.get(
        f"{base}/key/info",
        headers={"Authorization": f"Bearer {settings.litellm_key}"},
        timeout=30,
    )
    r.raise_for_status()
    info: dict[str, Any] = r.json().get("info", {})
    return {k: info.get(k) for k in ("spend", "max_budget", "budget_reset_at")}


def key_exhausted(settings: Settings) -> bool:
    try:
        info = key_info(settings)
    except Exception:
        return False  # cannot prove exhaustion: no overflow
    spend, cap = info.get("spend"), info.get("max_budget")
    return spend is not None and cap is not None and float(spend) >= float(cap)


class OverflowLedger:
    """Persistent total of overflow spend (OpenRouter/OpenAI), capped across all runs."""

    def __init__(self, path: Path) -> None:
        import sqlite3

        path.parent.mkdir(parents=True, exist_ok=True)
        self.db = sqlite3.connect(path, isolation_level=None, timeout=30)
        self.db.execute(
            "CREATE TABLE IF NOT EXISTS overflow (at REAL, provider TEXT, what TEXT, cost REAL)"
        )

    def total(self) -> float:
        return float(self.db.execute("SELECT COALESCE(SUM(cost), 0) FROM overflow").fetchone()[0])

    def add(self, provider: str, what: str, cost: float) -> None:
        import time

        self.db.execute(
            "INSERT INTO overflow VALUES (?, ?, ?, ?)", (time.time(), provider, what, cost)
        )


# One file for every thread and work dir: the $ cap is global, not per HEIRLOOM_WORK.
OVERFLOW_LEDGER = Path.home() / "heirloom" / "work" / "overflow.sqlite"


def overflow_allowance(settings: Settings) -> float:
    """USD that may still go to overflow keys: 0 unless the LiteLLM key is exhausted."""
    if not settings.openrouter_key or not key_exhausted(settings):
        return 0.0
    return max(0.0, settings.max_overflow_usd - OverflowLedger(OVERFLOW_LEDGER).total())


TRANSIENT = ("internalservererror", "serviceunavailable", "ratelimit", "timeout",
             "apiconnectionerror", "badgateway", "<html", "502", "503", "504", "429")  # fmt: skip
RETRY_DELAYS = (5.0, 15.0, 45.0)


def transient(exc: Exception) -> bool:
    text = f"{type(exc).__name__} {exc}".lower()
    return any(t in text for t in TRANSIENT)


class Router:
    sleep: Callable[[float], None] = staticmethod(__import__("time").sleep)

    def _gateway(self, litellm: Any, model: str, common: dict[str, Any]) -> Any:
        """The gateway call, retried with backoff on transient errors (5xx, 429, timeouts)."""
        for delay in (*RETRY_DELAYS, None):
            try:
                return litellm.completion(
                    model=f"openai/{model}",
                    api_base=self.settings.litellm_base,
                    api_key=self.settings.litellm_key,
                    **common,
                )
            except Exception as exc:
                if delay is None or not transient(exc):
                    raise
                self.sleep(delay)
        raise AssertionError("unreachable")

    def __init__(self, settings: Settings, budget: Budget) -> None:
        self.settings = settings
        self.budget = budget

    def complete(
        self,
        model: str,
        messages: Sequence[dict[str, str]],
        *,
        max_tokens: int = 4096,
        temperature: float = 0.0,
    ) -> Completion:
        """LiteLLM gateway first. Overflow (OpenRouter) only once the gateway key is
        exhausted, and only while the total overflow spend stays under the cap."""
        self.budget.check()
        import litellm

        common: dict[str, Any] = {
            "messages": list(messages),
            "max_tokens": max_tokens,
            "temperature": temperature,
            "timeout": 600,
        }
        try:
            resp = self._gateway(litellm, model, common)
            provider = "litellm-gateway"
        except Exception as exc:
            allowance = overflow_allowance(self.settings) if model in OPENROUTER_MODELS else 0.0
            if allowance <= 0:
                raise RuntimeError(
                    f"LiteLLM gateway failed for {model} (no overflow): {exc}"
                ) from exc
            resp = litellm.completion(
                model=f"openrouter/{OPENROUTER_MODELS[model]}",
                api_key=self.settings.openrouter_key,
                **common,
            )
            provider = "openrouter"
        usage = resp.usage
        cost = cost_of(model, int(usage.prompt_tokens), int(usage.completion_tokens))
        if provider == "openrouter":
            OverflowLedger(OVERFLOW_LEDGER).add(provider, model, cost)
        return Completion(
            text=str(resp.choices[0].message.content or ""),
            model=model,
            input_tokens=int(usage.prompt_tokens),
            output_tokens=int(usage.completion_tokens),
            cost_usd=cost,
            provider=provider,
        )

"""heirloom CLI (L0: cve, resume, clean, status)."""

from __future__ import annotations

import json
import shutil
import sys

import typer

from heirloom import config, guard
from heirloom.config import LINES, LineSpec, runtime_line
from heirloom.git_ops import git, git_ok, push
from heirloom.integrations import github
from heirloom.ledger import Ledger
from heirloom.pipeline.run import Result, execute

app = typer.Typer(add_completion=False, no_args_is_help=True)

EXIT = {"published": 0, "no_fix": 0, "evaluated": 0, "waiting_human": 2, "paused": 3}


def line_spec(line: str, tip: str | None, kind: str | None) -> LineSpec:
    """A configured line by name, or a runtime eval/distro line when --tip is given."""
    if tip is None:
        if line not in LINES:
            raise typer.BadParameter(f"unknown line {line!r}; pass --tip and --kind for a new one")
        return LINES[line]
    if kind not in ("eval", "distro"):
        raise typer.BadParameter("runtime lines need --kind eval or --kind distro")
    return runtime_line(line, tip, kind)  # type: ignore[arg-type]


def _report(r: Result) -> int:
    typer.echo(f"{r.cve} on {r.line}: {r.status}")
    typer.echo(f"  verdict     {r.verdict} ({r.reason})")
    typer.echo(f"  run         {r.run_id}")
    typer.echo(f"  cost        ${r.cost_usd:.4f}")
    if r.pr_url:
        typer.echo(f"  PR          {r.pr_url}")
    if r.checkpoint:
        typer.echo(f"  checkpoint  {r.checkpoint}")
    if r.message:
        typer.echo(f"  note        {r.message}")
    return EXIT.get(r.status, 1)


@app.command()
def cve(
    cve_id: str = typer.Argument(..., metavar="CVE"),
    line: str = "4.2",
    tip: str | None = typer.Option(None, help="Tip commit for a runtime (non-publishing) line."),
    kind: str | None = typer.Option(None, help="eval or distro (with --tip)."),
) -> None:
    """Bring one CVE to one line (resumes an unfinished run of the same CVE and line)."""
    raise typer.Exit(_report(execute(config.load(), cve_id, line_spec(line, tip, kind))))


@app.command()
def resume(cve_id: str | None = typer.Argument(None, metavar="[CVE]"), line: str = "4.2") -> None:
    """Continue every unfinished run (or one CVE's), reconciling unknown side effects."""
    s = config.load()
    ledger = Ledger(s.ledger_path)
    runs = [
        r
        for r in ledger.unfinished_runs()
        if r["status"] != "waiting_human" and (cve_id is None or r["cve"] == cve_id)
    ]
    ledger.close()
    if not runs:
        typer.echo("nothing to resume")
        raise typer.Exit(0)
    worst = 0
    for r in runs:
        typer.echo(f"resuming {r['cve']} on {r['line']} (run {r['run_id']}, was {r['status']})")
        spec = (
            LineSpec.from_json(json.loads(r["spec"]))
            if r["spec"]
            else line_spec(r["line"], None, None)
        )
        worst = max(worst, _report(execute(s, r["cve"], spec, run_id=r["run_id"])))
    raise typer.Exit(worst)


@app.command()
def clean(
    cve_id: str = typer.Argument(..., metavar="CVE"),
    line: str = "4.2",
    remote: bool = typer.Option(False, help="Also close the PR and delete the fork branch."),
) -> None:
    """Return a CVE × line to a clean state (run artifacts and checkpoints are kept)."""
    s = config.load()
    branch = f"heirloom/{cve_id.lower()}-{line}"
    if remote and not (line in LINES and LINES[line].publish):
        raise typer.BadParameter(f"--remote only applies to publishing lines, not {line!r}")
    if remote:
        with guard.publishing(LINES[line]):
            _clean_remote(s, cve_id, branch)
    trees = s.cve_dir(cve_id, line) / "trees"
    if trees.exists():
        for t in sorted(trees.iterdir()):
            git(s.django_repo, "worktree", "remove", "--force", str(t), check=False)
    git(s.django_repo, "worktree", "prune")
    if git_ok(s.django_repo, "rev-parse", "--verify", f"refs/heads/{branch}"):
        git(s.django_repo, "branch", "-q", "-D", branch)
    shutil.rmtree(s.cve_dir(cve_id, line), ignore_errors=True)
    ledger = Ledger(s.ledger_path)
    ledger.clear(cve_id, line)
    ledger.close()
    typer.echo(f"clean: {cve_id} on {line}")


def _clean_remote(s: config.Settings, cve_id: str, branch: str) -> None:
    """Close the PR and delete the fork branch (only reachable for publishing lines)."""
    found = github.find_pr(s.fork, branch)
    if found:
        github.close_pr(
            s.fork,
            int(found["number"]),
            "Closed by `heirloom clean --remote` for a clean-state rerun. The commit, its "
            "Entire checkpoint and the run artifacts stay available.",
        )
        typer.echo(f"closed {found['url']}")
    if git(s.django_repo, "ls-remote", s.fork_remote, f"refs/heads/{branch}").strip():
        push(s.django_repo, "-q", s.fork_remote, "--delete", branch)
        typer.echo(f"deleted {s.fork}:{branch}")


@app.command()
def backtest(
    set_name: str = typer.Option("django-4.2-2026", "--set"),
    pipeline: str = typer.Option("v2", help="v2 (full Heirloom) or v1 (naive baseline)."),
    cve_ids: list[str] | None = typer.Option(None, "--cve", help="Only these CVEs (repeatable)."),
    kinds: list[str] | None = typer.Option(None, "--kind", help="positive/negative/extra."),
    v1_budget: float = typer.Option(0.5, help="Per-case model budget for v1 conflict resolution."),
    rerun: bool = typer.Option(False, help="Re-run cases that already have a result row."),
) -> None:
    """E1 backtest against the fellows' real 4.2 patches; results -> evals/results.json."""
    from heirloom import backtest as bt

    if set_name != bt.SET:
        raise typer.BadParameter(f"unknown set {set_name!r}")
    s = config.load()
    out = s.root / "evals" / "results.json"
    todo = [
        c
        for c in bt.cases(s.django_repo)
        if (not cve_ids or c.cve in cve_ids) and (not kinds or c.kind in kinds)
    ]
    done = json.loads(out.read_text()).get("runs", {}).get(pipeline, {}) if out.exists() else {}
    if not rerun:
        todo = [
            c for c in todo if done.get(f"{c.cve}:{c.kind}", {}).get("verdict") in (None, "SKIPPED")
        ]
    # Positives first: negatives reuse their calibrated probes.
    todo.sort(key=lambda c: {"positive": 0, "extra": 1, "negative": 2}[c.kind])
    for c in todo:
        typer.echo(f"{pipeline} {c.cve} {c.kind} L={c.tip[:10]} truth={c.truth} ...")
        result = bt.run_v2(s, c) if pipeline == "v2" else bt.run_v1(s, c, v1_budget)
        row = bt.record(out, pipeline, c, result)
        typer.echo(
            f"  -> {row['verdict']} ({row.get('reason')}) correct={row['correct']} "
            f"fellows_test={row.get('fellows_test_passes')} ${row['cost_usd']} "
            f"{row['minutes']} min"
        )
        if pipeline == "v2" and c.truth == "AFFECTED" and row["verdict"] == "NOT_AFFECTED_PROVEN":
            typer.echo("STOP: false NOT_AFFECTED in v2")
            raise typer.Exit(4)
    summary = json.loads(out.read_text())["summary"].get(pipeline)
    typer.echo(json.dumps(summary, indent=1))


@app.command()
def detections(
    create: bool = typer.Option(False, help="Create the five §5 conditional detections."),
    delete_s4: bool = typer.Option(False, help="Delete the two S4 test detections."),
    report: bool = typer.Option(True, help="Write hits/trends + local mirror to evals/."),
) -> None:
    """neatlogs detections: create, clean up, and report (with the ledger's local mirror)."""
    import time

    from heirloom.integrations import neatlogs_api as api

    s = config.load()
    client = api.Api(s)
    if create:
        existing = {d["displayName"] for d in client.detections()}
        for name, rules in api.definitions().items():
            if name in existing:
                typer.echo(f"exists: {name}")
                continue
            code, _ = client.create(name, rules)
            typer.echo(f"create {name}: {code}")
    if delete_s4:
        for det in api.S4_TEST_DETECTIONS:
            code, _ = client.delete(det)
            typer.echo(f"delete {det}: {code}")
    if report:
        now = time.time()
        start = time.strftime("%Y-%m-%dT%H:00:00Z", time.gmtime(now - 86400))
        end = time.strftime("%Y-%m-%dT%H:00:00Z", time.gmtime(now + 3600))
        remote = {
            d["displayName"]: {
                "id": d["id"],
                "hits": client.hits(d["id"]),
                "trends": client.trends(d["id"], start, end),
            }
            for d in client.detections()
            if d["displayName"] in api.definitions()
        }
        ledger = Ledger(s.ledger_path)
        local: dict[str, int] = {}
        for h in ledger.hits():
            local[h["detection"]] = local.get(h["detection"], 0) + 1
        ledger.close()
        out = {
            "at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            "field_template": api.field("{name}"),
            "neatlogs": remote,
            "local_mirror": {name: local.get(name, 0) for name in api.definitions()},
        }
        path = s.root / "evals" / "detections.json"
        path.write_text(json.dumps(out, indent=2) + "\n")
        typer.echo(
            json.dumps(
                {
                    "neatlogs_hits": {k: v["hits"] for k, v in remote.items()},
                    "local_mirror": out["local_mirror"],
                }
            )
        )


@app.command()
