"""neatlogs tracing: one WORKFLOW root per CVE run, a child span per stage.

Verified against SDK 1.4.26 on 2026-10-11 (see docs/spikes.md):
* only a WORKFLOW root finalizes; AGENT/CHAIN roots stay pending or dead-letter;
* ``identify()`` has no ``parent_session_id``: the campaign link is a tag plus
  the ``heirloom.campaign_id`` attribute;
* the gateway reports zero cost, so ``heirloom.cost_usd`` is set explicitly;
* large attributes (the ~120 KB porter prompt) are suspected of stalling
  server-side PII redaction, so (§10.2) a ``mask`` truncates every string
  attribute over 16 KB, LLM span inputs/outputs are not captured (prompts live in
  the run artifacts) and PII redaction is limited to non-LLM/AGENT span types.

Every stage span carries all §5 attributes with explicit values (no empty
strings), and the five detection predicates are evaluated locally so the
before/after numbers never depend on ingestion timing.
"""

from __future__ import annotations

import hashlib
import os
from collections.abc import Callable, Iterator, Mapping
from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import Any

Attr = str | bool | int | float

MAX_ATTR_BYTES = 16 * 1024
# Span types that keep server-side PII redaction; LLM and AGENT spans are excluded.
PII_SPAN_TYPES = ["TOOL", "GUARDRAIL", "CHAIN", "WORKFLOW"]


def truncate_value(value: Any) -> Any:
    if not isinstance(value, str):
        return value
    raw = value.encode()
    if len(raw) <= MAX_ATTR_BYTES:
        return value
    digest = hashlib.sha256(raw).hexdigest()
    head = raw[:MAX_ATTR_BYTES].decode(errors="ignore")
    return f"{head}…[truncated {len(raw) - MAX_ATTR_BYTES} bytes sha256={digest}]"


def mask(span: dict[str, Any]) -> dict[str, Any]:
    """Truncate string attributes over 16 KB on the span and its events.

    Always returns the dict: returning None would make the SDK drop the span.
    """
    try:
        attrs = span.get("attributes")
        if isinstance(attrs, dict):
            for k, v in list(attrs.items()):
                attrs[k] = truncate_value(v)
        for event in span.get("events") or []:
            ev = event.get("attributes") if isinstance(event, dict) else None
            if isinstance(ev, dict):
                for k, v in list(ev.items()):
                    ev[k] = truncate_value(v)
    except Exception:  # a mask must never cost us the span
        pass
    return span


ATTR_DEFAULTS: dict[str, Attr] = {
    "cve": "NONE",
    "line": "NONE",
    "stage": "NONE",
    "verdict": "PENDING",
    "calibrated": False,
    "reach": False,
    "reason": "NONE",
    "tests_edited_after_red": False,
    "claims_unlinked": 0,
    "cost_usd": 0.0,
    "claim_id": "NONE",
    "campaign_id": "NONE",
}

# Child span kinds. GUARDRAIL children are verified under a WORKFLOW root.
STAGE_KINDS: dict[str, str] = {
    "locate": "TOOL",
    "c0": "GUARDRAIL",
    "probe": "AGENT",
    "calibrate": "GUARDRAIL",
    "presence": "GUARDRAIL",
    "adapt": "AGENT",
    "verify": "GUARDRAIL",
    "behaviour": "GUARDRAIL",
    "decide": "TOOL",
}


def _detections() -> dict[str, Callable[[Mapping[str, Attr]], bool]]:
    return {
        "not_affected_without_calibration": lambda a: (
            a["verdict"] == "NOT_AFFECTED_PROVEN" and a["calibrated"] is False
        ),
        "fix_applied_where_probe_passed": lambda a: (
            a["stage"] in ("adapt", "publish.commit") and a["verdict"] != "AFFECTED"
        ),
        "probe_never_reached_region": lambda a: (
            a["reach"] is False and a["verdict"] in ("AFFECTED", "NOT_AFFECTED_PROVEN")
        ),
        "claim_without_span": lambda a: int(a["claims_unlinked"]) > 0,
        "test_edited_after_red": lambda a: a["tests_edited_after_red"] is True,
    }


DETECTIONS = _detections()


def evaluate(attrs: Mapping[str, Attr]) -> list[str]:
    """Names of the detections whose predicate matches these span attributes."""
    full = {**ATTR_DEFAULTS, **attrs}
    return [name for name, pred in DETECTIONS.items() if pred(full)]


@dataclass
class StageSpan:
    stage: str
    attrs: dict[str, Attr]
    trace_id: str = "NONE"
    span_id: str = "NONE"
    _span: Any = None
    extra: dict[str, Attr] = field(default_factory=dict)

    def set(self, key: str, value: Attr) -> None:
        if key in ATTR_DEFAULTS:
            self.attrs[key] = value
        else:
            self.extra[key] = value

    def flush_attrs(self) -> dict[str, Attr]:
        full = {**ATTR_DEFAULTS, **self.attrs}
        if self._span is not None:
            for k, v in full.items():
                self._span.set_attribute(f"heirloom.{k}", v)
            for k, v in self.extra.items():
                self._span.set_attribute(f"heirloom.{k}", v)
        return full


def _ids(span: Any) -> tuple[str, str]:
    try:
        ctx = span.get_span_context()
        return format(ctx.trace_id, "032x"), format(ctx.span_id, "016x")
    except Exception:
        return "NONE", "NONE"


class Telemetry:
    """Wraps the SDK; a no-op (but still evaluating detections) without an API key."""

    def __init__(self) -> None:
        self.enabled = False
        self._nl: Any = None
        self.root_trace_id = "NONE"
        self.root_span_id = "NONE"

    def init(self, api_key: str, tags: list[str]) -> None:
        if not api_key or os.environ.get("HEIRLOOM_NO_TELEMETRY"):
            return
        # OpenInference's default TraceConfig reads these: no prompt/response content
        # on LiteLLM (porter) spans. Full prompts are kept in the run artifacts.
        os.environ.setdefault("OPENINFERENCE_HIDE_INPUTS", "true")
        os.environ.setdefault("OPENINFERENCE_HIDE_OUTPUTS", "true")
        import neatlogs

        neatlogs.init(
            api_key=api_key,
            workflow_name="heirloom",
            instrumentations=["litellm"],
            tags=tags,
            mask=mask,
            pii_span_types=PII_SPAN_TYPES,
        )
        self._nl = neatlogs
        self.enabled = True

    @contextmanager
    def cve_root(self, cve: str, line: str, run_id: str, campaign_id: str) -> Iterator[None]:
        if not self.enabled:
            yield
            return
        nl = self._nl
        with (
            nl.identify(session_id=f"cve-{cve}-{line}-{run_id}"),
            nl.trace(f"cve-{cve}-{line}", kind="WORKFLOW") as root,
        ):
            for k, v in {
                **ATTR_DEFAULTS,
                "cve": cve,
                "line": line,
                "stage": "root",
                "campaign_id": campaign_id,
            }.items():
                root.set_attribute(f"heirloom.{k}", v)
            root.set_attribute("heirloom.run_id", run_id)
            self.root_trace_id, self.root_span_id = _ids(root)
            yield

    @contextmanager
    def stage(self, stage: str, base: Mapping[str, Attr]) -> Iterator[StageSpan]:
        handle = StageSpan(stage, {**base, "stage": stage})
        if not self.enabled:
            yield handle
            return
        kind = STAGE_KINDS.get(stage.split(".")[0], "TOOL")
        with self._nl.trace(stage, kind=kind) as span:
            handle._span = span
            handle.trace_id, handle.span_id = _ids(span)
            try:
                yield handle
            finally:
                handle.flush_attrs()

    def flush(self) -> None:
        if self.enabled:
            self._nl.flush()

    def shutdown(self) -> None:
        if self.enabled:
            self._nl.flush()
            self._nl.shutdown()
            self.enabled = False


def trace_url(template: str, trace_id: str, span_id: str) -> str | None:
    if trace_id in ("", "NONE") or not template:
        return None
    return template.format(trace_id=trace_id, span_id=span_id)
"""neatlogs Public API: the five §5 conditional detections, hits and trends.

Field spelling for custom span attributes is not documented and, as of
2026-10-11, none of ten tried spellings produced a hit (evals/neatlogs_ingestion.json),
while built-in fields (``status``) did. The spelling is therefore a template,
``NEATLOGS_ATTR_FIELD`` (default ``heirloom.{name}``), to be confirmed in the UI.
"""

from __future__ import annotations

import hashlib
import os
import uuid
from typing import Any

import httpx

from heirloom.config import Settings

BASE = "https://app.neatlogs.com/api/v1/public"
NEGATIVE_GROUP = "0410d37c-bea2-4360-a15c-ef6fb0f949f7"  # the project's "Negative" group
S4_TEST_DETECTIONS = {
    "007f83c6-8086-485f-9f82-a8f29ab3bbe2",
    "cc80fec3-df7f-49c4-9c7b-8b66df828532",
}


def idempotency_key(name: str) -> str:
    """Deterministic UUIDv4 (the API requires a v4 shape)."""
    return str(uuid.UUID(bytes=hashlib.sha256(name.encode()).digest()[:16], version=4))


def field(name: str) -> str:
    return os.environ.get("NEATLOGS_ATTR_FIELD", "heirloom.{name}").format(name=name)


def rule(name: str, operator: str, value: Any) -> dict[str, Any]:
    return {"type": "rule", "field": field(name), "operator": operator, "value": value}


def definitions() -> dict[str, list[dict[str, Any]]]:
    """The five detections as AND-groups over span attributes (mirrors neatlogs.DETECTIONS)."""
    return {
        "not_affected_without_calibration": [
            rule("verdict", "=", "NOT_AFFECTED_PROVEN"),
            rule("calibrated", "=", False),
        ],
        "fix_applied_where_probe_passed": [
            rule("stage", "in", ["adapt", "publish.commit"]),
            rule("verdict", "!=", "AFFECTED"),
        ],
        "probe_never_reached_region": [
            rule("reach", "=", False),
            rule("verdict", "in", ["AFFECTED", "NOT_AFFECTED_PROVEN"]),
        ],
        "claim_without_span": [rule("claims_unlinked", ">", 0)],
        "test_edited_after_red": [rule("tests_edited_after_red", "=", True)],
    }


class Api:
    def __init__(self, s: Settings) -> None:
        self.headers = {
            "Authorization": f"Bearer {s.neatlogs_service_token}",
            "x-project-id": s.neatlogs_project_id,
        }

    def call(
        self,
        method: str,
        path: str,
        body: dict[str, Any] | None = None,
        params: dict[str, Any] | None = None,
        key: str | None = None,
    ) -> tuple[int, Any]:
        h = dict(self.headers)
        if method != "GET":
            h["idempotency-key"] = key or str(uuid.uuid4())
        r = httpx.request(method, BASE + path, headers=h, json=body, params=params, timeout=60)
        try:
            return r.status_code, r.json()
        except ValueError:
            return r.status_code, r.text[:500]

    def detections(self) -> list[dict[str, Any]]:
        code, data = self.call("GET", "/detections", params={"limit": 50})
        return list(data["data"]["detections"]) if code == 200 else []

    def create(self, name: str, rules: list[dict[str, Any]]) -> tuple[int, Any]:
        body = {
            "displayName": name,
            "groupId": NEGATIVE_GROUP,
            "type": "conditional",
            "isActive": True,
            "runOn": {"frequency": "trace"},
            "config": {"root": {"type": "group", "logic": "AND", "children": rules}},
        }
        return self.call("POST", "/detections", body, key=idempotency_key(f"heirloom-{name}-v1"))

    def delete(self, detection_id: str) -> tuple[int, Any]:
        # The API requires the id echoed back as a confirmation.
        return self.call("DELETE", f"/detections/{detection_id}", {"confirmation": detection_id})

    def hits(self, detection_id: str) -> int:
        code, data = self.call("GET", f"/detections/{detection_id}/hits", params={"limit": 100})
        return len(data["data"]["hits"]) if code == 200 else -1

    def trends(self, detection_id: str, start: str, end: str) -> Any:
        params = {"granularity": "hour", "from": start, "to": end}
        code, data = self.call("GET", f"/detections/{detection_id}/trends", params=params)
        return data["data"]["buckets"] if code == 200 else data

"""LOCATE (deterministic): the upstream fix, its trees, tests and advisory text."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from heirloom.git_ops import commit_diff, git, is_ancestor, parse_diff, rev_parse, show_file
from heirloom.integrations.neatlogs import StageSpan
from heirloom.pipeline.calibrate import symbols
from heirloom.pipeline.context import Ctx, StageFailed
from heirloom.pipeline.fixes import fix_diff
from heirloom.sources.django_security import load


def changed_test_ids(repo: Path, commits: list[str], files: list[str]) -> list[str]:
    """Dotted ids of the test methods the commits add OR modify.

    Fixes often tighten existing tests instead of adding new ones (e.g. the fellows'
    4.2 commit for CVE-2026-1287), so every changed new-side line counts. Each
    commit's hunks are located in that commit's own version of the file.
    """
    ids: set[str] = set()
    for sha in commits:
        for d in parse_diff(commit_diff(repo, sha, *files)) if files else []:
            if not d.new_path or not d.new_path.endswith(".py"):
                continue
            syms = [
                x
                for x in symbols(show_file(repo, sha, d.new_path) or "")
                if "." in x.qualname and x.qualname.rsplit(".", 1)[-1].startswith("test")
            ]
            module = d.new_path.removeprefix("tests/").removesuffix(".py").replace("/", ".")
            for h in d.hunks:
                for n in range(h.new_start, h.new_start + h.new_count):
                    inside = [x for x in syms if x.start <= n <= x.end]
                    if inside:
                        ids.add(f"{module}.{max(inside, key=lambda x: x.start).qualname}")
    return sorted(ids)


def upstream_test_ids(ctx: Ctx, fixes: list[str], test_files: list[str]) -> list[str]:
    """Test methods the upstream fix commits add or modify."""
    return changed_test_ids(ctx.repo, fixes, test_files)


def advisory_text(ctx: Ctx, fixes: list[str], title: str) -> str:
    """The release-notes paragraphs the fix commits add (Django's published advisory text)."""
    notes = [
        line
        for f in parse_diff(fix_diff(ctx.repo, fixes, "docs/releases/"))
        for h in f.hunks
        for line in h.added
    ]
    body = "\n".join(notes).strip()
    return f"{title}\n\n{body}" if body else title


def run(ctx: Ctx) -> dict[str, Any]:
    def body(span: StageSpan) -> dict[str, Any]:
        git(ctx.repo, "fetch", "-q", "origin", "main")
        if ctx.spec.publish and ctx.spec.base_branch:
            git(ctx.repo, "fetch", "-q", ctx.s.fork_remote, ctx.spec.base_branch)
        archive_ref = rev_parse(ctx.repo, ctx.archive_ref)
        advisories = load(ctx.repo, archive_ref)
        if ctx.cve not in advisories:
            raise StageFailed(f"{ctx.cve} is not in security.txt at {archive_ref[:10]}")
        adv = advisories[ctx.cve]
        series = adv.first_series(ctx.spec.upstreams)
        fixes = [rev_parse(ctx.repo, sha) for sha in adv.fix_commits(series)]
        messages = [git(ctx.repo, "log", "-1", "--format=%B", sha) for sha in fixes]
        first = messages[0]
        if ctx.cve not in first or not (f"Fixed {ctx.cve}" in first or "Backport of" in first):
            raise StageFailed(
                f"{fixes[0][:10]} message does not say 'Fixed {ctx.cve}'/'Backport of'"
            )
        for sha, msg in zip(fixes[1:], messages[1:], strict=True):
            if ctx.cve not in msg:  # follow-ups say "Refs CVE-…"
                raise StageFailed(f"follow-up {sha[:10]} does not mention {ctx.cve}")
        files = sorted(
            {
                f
                for sha in fixes
                for f in git(ctx.repo, "diff", "--name-only", f"{sha}^", sha).split()
            }
        )
        fix_files = [f for f in files if f.startswith("django/")]
        test_files = [f for f in files if f.startswith("tests/")]
        if not fix_files:
            raise StageFailed(f"{ctx.cve}'s {series} fix changes no django/ files")
        fix = fixes[-1]  # U⁺
        um = rev_parse(ctx.repo, f"{fixes[0]}^")  # U⁻
        tip = rev_parse(ctx.repo, ctx.spec.tip)
        if ctx.spec.publish and ctx.spec.base_branch:
            base = rev_parse(ctx.repo, f"{ctx.s.fork_remote}/{ctx.spec.base_branch}")
            if not is_ancestor(ctx.repo, tip, base):
                raise StageFailed(
                    f"{ctx.spec.base_branch} does not contain the line tip {tip[:10]}"
                )
        else:
            base = tip  # non-publishing lines work on the tip itself, never the fork
        merge_base = git(ctx.repo, "merge-base", um, tip).strip()
        subject = first.splitlines()[0]
        message = "\n\n".join(messages)
        span.set("claim_id", f"{ctx.cve}/{ctx.line}/locate")
        span.set("fix_sha", fix)
        return {
            "cve": ctx.cve,
            "title": adv.title,
            "date": adv.date.isoformat(),
            "url": adv.url or "",
            "archive_ref": archive_ref,
            "series": series,
            "fixes": fixes,
            "fix": fix,
            "um": um,
            "tip": tip,
            "base": base,
            "merge_base": merge_base,
            "subject": subject,
            "message": message,
            "fix_files": fix_files,
            "test_files": test_files,
            "upstream_test_ids": upstream_test_ids(ctx, fixes, test_files),
            "advisory": advisory_text(ctx, fixes, adv.title),
        }

    return ctx.stage("locate", {"cve": ctx.cve, "line": ctx.line, "tip": ctx.spec.tip}, body)
"""Parse Django's security archive (``docs/releases/security.txt``).

Each entry looks like::

    October 6, 2026 - :cve:`2026-87975`
    -----------------------------------

    Privilege abuse in model formsets with editable primary keys.
    `Full description
    <https://www.djangoproject.com/weblog/2026/oct/06/security-releases/>`__

    * Django 5.2 :commit:`(patch) <ff27883ca055aa9ab23015b50674a5b10dfe5a41>`
"""

from __future__ import annotations

import re
import subprocess
from dataclasses import dataclass, field
from datetime import date, datetime
from pathlib import Path

HEADER = re.compile(r"^(?P<date>[A-Z][a-z]+ \d{1,2}, \d{4}) - :cve:`(?P<id>\d{4}-\d{4,})`\s*$")
COMMIT = re.compile(
    r"^\*\s+Django\s+(?P<branch>\d+(?:\.\d+)*)\s+:commit:`[^<`]*<(?P<sha>[0-9a-f]{40})>`"
)
FULL_DESCRIPTION = re.compile(r"`Full description\s*<(?P<url>[^>]+)>`__", re.S)


class AdvisoryError(LookupError):
    pass


@dataclass(frozen=True)
class FixCommit:
    label: str  # as printed in the archive: "5.2", or a follow-up release such as "5.2.18"
    sha: str

    @property
    def series(self) -> str:
        return ".".join(self.label.split(".")[:2])


@dataclass(frozen=True)
class Advisory:
    cve: str
    date: date
    title: str
    url: str | None
    fixes: tuple[FixCommit, ...] = field(default_factory=tuple)

    @property
    def commits(self) -> dict[str, list[str]]:
        """Every fix commit per branch series, in archive order (follow-ups included)."""
        out: dict[str, list[str]] = {}
        for f in self.fixes:
            out.setdefault(f.series, []).append(f.sha)
        return out

    def fix_commits(self, series: str) -> list[str]:
        try:
            return self.commits[series]
        except KeyError:
            raise AdvisoryError(
                f"{self.cve} has no Django {series} commit (has: {sorted(self.commits)})"
            ) from None

    def first_series(self, candidates: tuple[str, ...]) -> str:
        """The first candidate series (preferred upstream, then fallbacks) with a fix."""
        for series in candidates:
            if series in self.commits:
                return series
        raise AdvisoryError(f"{self.cve}: none of {list(candidates)} has a fix commit")


def parse_security_txt(text: str) -> dict[str, Advisory]:
    lines = text.splitlines()
    starts = [i for i, line in enumerate(lines) if HEADER.match(line)]
    advisories: dict[str, Advisory] = {}
    for n, start in enumerate(starts):
        end = starts[n + 1] if n + 1 < len(starts) else len(lines)
        m = HEADER.match(lines[start])
        assert m is not None
        body = lines[start + 1 : end]
        if body and set(body[0].strip()) == {"-"}:
            body = body[1:]
        fixes: list[FixCommit] = []
        prose: list[str] = []
        for line in body:
            c = COMMIT.match(line.strip())
            if c:
                fixes.append(FixCommit(c["branch"], c["sha"]))
            elif not fixes and not line.startswith(("Versions affected", "~~~")):
                prose.append(line)
        text_block = " ".join(" ".join(prose).split())
        url_match = FULL_DESCRIPTION.search(text_block)
        title = text_block[: url_match.start()] if url_match else text_block
        cve = f"CVE-{m['id']}"
        advisories[cve] = Advisory(
            cve=cve,
            date=datetime.strptime(m["date"], "%B %d, %Y").date(),
            title=" ".join(title.split()),
            url=url_match["url"].strip() if url_match else None,
            fixes=tuple(fixes),
        )
    return advisories


def read_security_txt(repo: Path, ref: str = "origin/main") -> str:
    return subprocess.run(
        ["git", "-C", str(repo), "show", f"{ref}:docs/releases/security.txt"],
        check=True,
        capture_output=True,
        text=True,
    ).stdout


def load(repo: Path, ref: str = "origin/main") -> dict[str, Advisory]:
    return parse_security_txt(read_security_txt(repo, ref))
"""An upstream fix is an ordered list of commits (e.g. CVE-2026-15830: 5.2 + the 5.2.18
follow-up). U⁻ is the first commit's parent and U⁺ the last commit; each commit's
hunks are analysed against its own parent."""

from __future__ import annotations

from collections.abc import Sequence
from pathlib import Path
from typing import Any

from heirloom.git_ops import FileDiff, commit_diff, parse_diff


def fixes_of(loc: dict[str, Any]) -> list[str]:
    """The fix commits in archive order (ledger rows from before §10 have only ``fix``)."""
    return list(loc.get("fixes") or [loc["fix"]])


def fix_diff(repo: Path, fixes: Sequence[str], *paths: str, context: int = 0) -> str:
    """Each commit's diff against its own parent, concatenated in order."""
    return "".join(commit_diff(repo, sha, *paths, context=context) for sha in fixes)


def fix_file_diffs(repo: Path, fixes: Sequence[str], *paths: str) -> list[tuple[str, FileDiff]]:
    """(parent ref, file diff) per commit and file, with line numbers in that parent."""
    return [(f"{sha}^", d) for sha in fixes for d in parse_diff(commit_diff(repo, sha, *paths))]

