                input=test_diff,
                capture_output=True,
                text=True,
            )
            upstream_applied = proc.returncode == 0 and "<<<<<<<" not in git(beh, "diff")
            if upstream_applied:
                ids += loc["upstream_test_ids"]
            else:
                ctx.tree("Beh", loc["base"], files)
                git(beh, "apply", "--whitespace=nowarn", "-", input=adapt["patch"])
        runner = ctx.runner()
        tag = adapt["patch_sha"][:8]
        r_up = runner.run(up, ids, log_path=ctx.log("behaviour", tag, "Up.log"))
        r_fix = runner.run(beh, ids, log_path=ctx.log("behaviour", tag, "Lfix.log"))
        compared: list[str] = []
        not_runnable: list[str] = []
        diffs: list[dict[str, str]] = []
        for t in sorted(set(r_up.tests) | set(r_fix.tests)):
            a, b = r_up.tests.get(t), r_fix.tests.get(t)
            if a is None or b is None or "ERROR" in (a.outcome, b.outcome):
                not_runnable.append(t)
                continue
            compared.append(t)
            if a.outcome != b.outcome or (
                a.outcome == "FAIL" and _exc_kind(a.detail) != _exc_kind(b.detail)
            ):
                diffs.append(
                    {
                        "test": t,
                        "upstream": f"{a.outcome} {a.detail}".strip(),
                        "backport": f"{b.outcome} {b.detail}".strip(),
                    }
                )
        # Upstream tests often cannot run on the old line (diverged test files); a
        # changed user-visible message is still an observable difference.
        diffs += missing_messages(ctx.repo, fixes_of(loc), loc["fix_files"], beh)
        span.set("behaviour_same", not diffs)
        span.set("behaviour_compared", len(compared))
        return {
            "same": not diffs and bool(compared),
            "diffs": diffs,
            "compared": compared,
            "not_runnable": not_runnable,
            "upstream_tests_applied": upstream_applied,
            "kind": "BEHAVIOUR_DIFF" if diffs else ("NOTHING_COMPARABLE" if not compared else ""),
        }

    return ctx.stage(
        "behaviour",
        {"patch": adapt["patch_sha"], "probe": probe["sha"], "fix": loc["fix"], "v": VERSION},
        body,
    )
"""The PR claims table: every claim links to its span and to a run artifact, or is struck."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass

from heirloom.integrations.neatlogs import trace_url


@dataclass(frozen=True)
class SpanLink:
    trace_id: str
    span_id: str


@dataclass(frozen=True)
class Link:
    label: str
    url: str


@dataclass(frozen=True)
class Claim:
    id: str
    text: str
    span: SpanLink | None
    evidence: tuple[Link, ...]

    @property
    def has_span(self) -> bool:
        return self.span is not None and self.span.trace_id not in ("", "NONE")

    @property
    def has_evidence(self) -> bool:
        return bool(self.evidence) and all(e.url for e in self.evidence)

    @property
    def linked(self) -> bool:
        return self.has_span and self.has_evidence


def _cell(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def render(claims: Sequence[Claim], template: str) -> tuple[str, int]:
    """Markdown table and the number of struck (unlinked) claims."""
    rows = ["| # | Claim | Span | Evidence |", "|---|---|---|---|"]
    unlinked = 0
    for c in claims:
        if c.has_span and c.span is not None:
            url = trace_url(template, c.span.trace_id, c.span.span_id)
            label = f"`{c.span.span_id[:8]}` (trace `{c.span.trace_id[:12]}`)"
            span_cell = f"[{label}]({url})" if url else label
        else:
            span_cell = "none"
        evidence = " · ".join(f"[{_cell(e.label)}]({e.url})" for e in c.evidence if e.url) or "none"
        text = _cell(c.text)
        if not c.linked:
            unlinked += 1
            missing = " and ".join(
                m for m, ok in (("span", c.has_span), ("artifact", c.has_evidence)) if not ok
            )
            text = f"~~{text}~~ (no {missing})"
        rows.append(f"| {c.id} | {text} | {span_cell} | {evidence} |")
    return "\n".join(rows), unlinked

def feedback_for(cal: dict[str, Any], verdict: Presence) -> str | None:
    """What the porter is told after a failed calibration (never quotes the fix)."""
    if verdict.verdict != "UNPROVEN" or verdict.reason not in RETRYABLE:
        return None
    mapped = cal.get("mapped") or []
    c1 = verdict.gates.get("C1")
    if c1 is not None and c1.ok and mapped and all(m["how"] == "absent" for m in mapped):
        # C1 holds and no fix symbol exists on L: no new probe can reach L's version
        # of the fix (there is none), so a retry only costs (§10.4 absent-symbol path).
        return None

    def describe(tree: str, runs: list[dict[str, Any]]) -> str:
        outcomes = ", ".join(r["outcome"] for r in runs)
        details = {k: v for r in runs for k, v in r["details"].items()}
        lines = [f"- {tree}: {outcomes}"]
        lines += [f"    {k.rsplit('.', 1)[-1]}: {v[:300]}" for k, v in list(details.items())[:6]]
        lines += [f"    harness: {h[:300]}" for r in runs[:1] for h in r["harness_errors"][:3]]
        return "\n".join(lines)

    return "\n".join(
        [
            f"Calibration rejected the probe: {verdict.reason} ({verdict.detail}).",
            "Required: FAIL (AssertionError) on the vulnerable trees, PASS on the fixed tree,",
            "no ERROR or SKIP anywhere, identical failing tests on every run.",
            describe("vulnerable 5.2 tree (U⁻)", cal["um"]),
            describe("fixed 5.2 tree (U⁺)", cal["up"]),
            describe("Django 4.2 (L)", cal["lt"]),
        ]
    )


